import 'dart:io';

void main(List<String> arguments) {
  final root = File.fromUri(Platform.script).parent.parent;
  final source = File('${root.path}/pubspec.yaml').readAsStringSync();
  final version = RegExp(
    r'^version:\s*(\d+\.\d+\.\d+\+\d+)\s*$',
    multiLine: true,
  ).firstMatch(source)?.group(1);
  if (version == null) {
    throw const FormatException(
      'pubspec.yaml needs a release and build number',
    );
  }
  final text =
      '// Generated by tools/sync_version.dart from pubspec.yaml.\n'
      "const appVersion = '$version';\n"
      "const appReleaseVersion = '${version.split('+').first}';\n";
  final output = File('${root.path}/lib/app_version.g.dart');
  if (arguments.contains('--check')) {
    if (!output.existsSync() || output.readAsStringSync() != text) {
      stderr.writeln('Run dart tools/sync_version.dart before building.');
      exitCode = 1;
    }
  } else {
    output.writeAsStringSync(text);
  }
}
